# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_channel() {
    flutter channel 2>/dev/null | sed -n 's/^[* ]*\([^ ]*\) (.*/\1/p'
}

_choice_device_id() {
    _argc_util_cache 60 _helper_flutter_device_ids "flutter:devices"
}

_choice_emulator_id() {
    flutter emulators 2>/dev/null | sed -n 's/^[[:space:]]*\([^[:space:]]*\) • .*/\1/p' | grep -v '^Id$'
}

_choice_pub_global_package() {
    flutter pub global list 2>/dev/null | gawk 'NF >= 2 { print $1 }'
}

_choice_pubspec_dependency() {
    local file
    file="$(_argc_util_path_search_parent pubspec.yaml)"
    [[ -n $file ]] || return 0
    gawk '
        /^[^ #]/ { in_deps = ($0 ~ /^(dependencies|dev_dependencies):/); next }
        in_deps && /^  [A-Za-z0-9_][A-Za-z0-9_.-]*:/ {
            sub(/:.*/, "")
            sub(/^  /, "")
            print
        }
    ' "$file"
}

_helper_flutter_device_ids() {
    flutter devices --machine 2>/dev/null | jq -b -r '.[] | "\(.id)\t\(.name)"'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
